const body = $input.first().json.body ?? {};

// Cap the message so a pasted wall of text can't blow up the prompt budget.
const message = String(body.message ?? '').trim().slice(0, 1000);

// Memory is keyed on this. Falling back to the execution id means a missing
// sessionId degrades to a one-off conversation rather than sharing a thread
// with every other visitor.
const sessionId = String(body.sessionId ?? '').trim() || `anon-${$execution.id}`;

if (!message) {
  throw new Error('Request had no message.');
}

return [{ json: { message, sessionId } }];

const doc = $input.first().json;

// The Docs API returns a deeply nested document resource. Walk it and keep
// only the text runs, so the agent reads clean prose instead of API scaffolding.
function collect(elements = []) {
  let out = '';

  for (const el of elements) {
    if (el.paragraph) {
      for (const pe of el.paragraph.elements ?? []) {
        out += pe.textRun?.content ?? '';
      }
    } else if (el.table) {
      for (const row of el.table.tableRows ?? []) {
        for (const cell of row.tableCells ?? []) {
          out += collect(cell.content);
        }
      }
    } else if (el.tableOfContents) {
      out += collect(el.tableOfContents.content);
    }
  }

  return out;
}

const kbText = collect(doc.body?.content).replace(/\n{3,}/g, '\n\n').trim();

if (!kbText) {
  throw new Error('Knowledge base doc came back empty — check the Doc URL and that the credential can read it.');
}

return [{ json: { kbText, kbTitle: doc.title ?? 'Knowledge base' } }];
